from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Mapping, MutableMapping, Optional

DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_MODEL = \"gpt-4.1\"
DEFAULT_TIMEOUT = 60


class OpenAIError(RuntimeError):
    \"\"\"Raised when the Responses API returns an error.\"\"\"

    def __init__(self, message: str, status: Optional[int] = None, payload: Any = None) -> None:
        super().__init__(message)
        self.status = status
        self.payload = payload


class OpenAIClient:
    \"\"\"Minimal Responses API client that never logs prompt contents.\"\"\"

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: str = DEFAULT_BASE_URL,
        organization: Optional[str] = None,
        project: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
    ) -> None:
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise OpenAIError(\"OPENAI_API_KEY is required\")
        self.base_url = base_url.rstrip(\"/\")
        self.organization = organization or os.environ.get(\"OPENAI_ORG_ID\")
        self.project = project or os.environ.get(\"OPENAI_PROJECT\")
        self.timeout = timeout

    def _headers(self) -> dict[str, str]:
        headers = {
            \"Authorization\": f\"Bearer {self.api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"application/json\",
        }
        if self.organization:
            headers[\"OpenAI-Organization\"] = self.organization
        if self.project:
            headers[\"OpenAI-Project\"] = self.project
        return headers

    def _request(self, method: str, path: str, body: Optional[Mapping[str, Any]] = None) -> Any:
        url = f\"{self.base_url}{path}\"
        data = None if body is None else json.dumps(body).encode(\"utf-8\")
        request = urllib.request.Request(url, data=data, headers=self._headers(), method=method)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read()
        except urllib.error.HTTPError as exc:
            raw = exc.read()
            payload: Any
            try:
                payload = json.loads(raw.decode(\"utf-8\")) if raw else None
            except json.JSONDecodeError:
                payload = raw.decode(\"utf-8\", errors=\"replace\")
            message = _error_message(payload) or f\"HTTP {exc.code}\"
            raise OpenAIError(message, status=exc.code, payload=payload) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Network error: {exc.reason}\") from None

        if not raw:
            return None
        try:
            return json.loads(raw.decode(\"utf-8\"))
        except json.JSONDecodeError as exc:
            raise OpenAIError(\"Invalid JSON in Responses API reply\") from exc

    def respond(
        self,
        prompt: str,
        *,
        model: str = DEFAULT_MODEL,
        instructions: Optional[str] = None,
        extra: Optional[Mapping[str, Any]] = None,
    ) -> dict[str, Any]:
        \"\"\"Send a private text prompt and return the raw Responses API payload.\"\"\"
        if not isinstance(prompt, str) or not prompt.strip():
            raise ValueError(\"prompt must be a non-empty string\")

        body: MutableMapping[str, Any] = {
            \"model\": model,
            \"input\": prompt,
            \"store\": False,
        }
        if instructions:
            body[\"instructions\"] = instructions
        if extra:
            body.update(extra)

        return self._request(\"POST\", \"/responses\", body)

    def prompt_text(
        self,
        prompt: str,
        *,
        model: str = DEFAULT_MODEL,
        instructions: Optional[str] = None,
        extra: Optional[Mapping[str, Any]] = None,
    ) -> str:
        \"\"\"Send a private text prompt and return concatenated output text.\"\"\"
        payload = self.respond(prompt, model=model, instructions=instructions, extra=extra)
        text = extract_output_text(payload)
        if text is None:
            raise OpenAIError(\"Responses API returned no output text\", payload=payload)
        return text


def extract_output_text(payload: Mapping[str, Any]) -> Optional[str]:
    \"\"\"Pull output_text from a Responses API payload when present.\"\"\"
    direct = payload.get(\"output_text\")
    if isinstance(direct, str) and direct:
        return direct

    chunks: list[str] = []
    for item in payload.get(\"output\") or []:
        if not isinstance(item, Mapping):
            continue
        for content in item.get(\"content\") or []:
            if not isinstance(content, Mapping):
                continue
            if content.get(\"type\") in {\"output_text\", \"text\"}:
                text = content.get(\"text\")
                if isinstance(text, str) and text:
                    chunks.append(text)
    return \"\".join(chunks) if chunks else None


def _error_message(payload: Any) -> Optional[str]:
    if isinstance(payload, Mapping):
        error = payload.get(\"error\")
        if isinstance(error, Mapping):
            message = error.get(\"message\")
            if isinstance(message, str):
                return message
        message = payload.get(\"message\")
        if isinstance(message, str):
            return message
    if isinstance(payload, str) and payload.strip():
        return payload
    return None


def send_private_prompt(prompt: str, **kwargs: Any) -> str:
    \"\"\"Convenience wrapper that sends a private prompt and returns text.\"\"\"
    return OpenAIClient().prompt_text(prompt, **kwargs)


if __name__ == \"__main__\":
    import argparse
    import sys

    parser = argparse.ArgumentParser(description=\"Send a private prompt to the Responses API.\")
    parser.add_argument(\"prompt\", nargs=\"?\", help=\"Prompt text. Reads stdin when omitted.\")
    parser.add_argument(\"--model\", default=DEFAULT_MODEL)
    parser.add_argument(\"--instructions\")
    args = parser.parse_args()
    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    try:
        print(send_private_prompt(prompt, model=args.model, instructions=args.instructions))
    except OpenAIError as exc:
        print(exc, file=sys.stderr)
        sys.exit(1)
''')
